#!/usr/bin/env python3
"""Claude Code Bash hook. PreToolUse: deny a heredoc that writes a .py file.
PostToolUse: parse every .py file the command named and that changed in the last two minutes."""
import ast
import json
import re
import sys
import time
from pathlib import Path

HEREDOC = re.compile(r"<<-?\s*['\"]?(\w+)['\"]?")
REDIRECT_PY = re.compile(r"(?:>>?|\btee(?:\s+-a)?)\s*['\"]?[^\s'\"<>|;&]+\.py\b")
PY_WRITE = re.compile(r"open\(\s*['\"][^'\"]+\.py['\"]\s*,\s*['\"][wax]"
                      r"|Path\(\s*['\"][^'\"]+\.py['\"]\s*\)\.write_text")
PY_NAME = re.compile(r"[\w./\\-]+\.py\b")


def split(cmd):
    """Shell text and heredoc bodies, kept apart: a body that mentions x.py is not a redirect."""
    shell, bodies, lines, i = [], [], cmd.split("\n"), 0
    while i < len(lines):
        shell.append(lines[i])
        opener = HEREDOC.search(lines[i])
        i += 1
        if opener:
            body = []
            while i < len(lines) and lines[i].strip() != opener.group(1):
                body.append(lines[i])
                i += 1
            bodies.append("\n".join(body))
            i += 1
    return "\n".join(shell), bodies


def writes_py_by_heredoc(cmd):
    shell, bodies = split(cmd)
    if not bodies:
        return False
    if REDIRECT_PY.search(shell):
        return True
    return "python" in shell and any(PY_WRITE.search(body) for body in bodies)


def broken_py(cmd, cwd):
    broken = []
    for name in sorted(set(PY_NAME.findall(cmd))):
        path = Path(cwd, name)
        if path.is_file() and time.time() - path.stat().st_mtime < 120:
            try:
                ast.parse(path.read_text(encoding="utf-8"))
            except SyntaxError as err:
                broken.append(f"{name} line {err.lineno}: {err.msg}")
    return broken


def main():
    event = json.load(sys.stdin)
    cmd = (event.get("tool_input") or {}).get("command") or ""
    if event.get("hook_event_name") == "PreToolUse" and writes_py_by_heredoc(cmd):
        reason = ("This heredoc writes a .py file. On Windows the Bash tool halves runs of backslashes "
                  "(except before a double quote) before bash reads the command, so escapes in string "
                  "literals can change. Use the Write tool.")
        print(json.dumps({"hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason}}))
    elif event.get("hook_event_name") == "PostToolUse":
        broken = broken_py(cmd, event.get("cwd") or ".")
        if broken:
            print(json.dumps({"hookSpecificOutput": {
                "hookEventName": "PostToolUse",
                "additionalContext": "A .py file no longer parses: " + "; ".join(broken)}}))


if __name__ == "__main__":
    main()
